-- 046: catálogos de proveedores farmacia 2026 (listas de precios descargadas 2026-10-20):
-- REVE, DermaZone Elite y BioElite (vía OmicronLab), HD Cosmetic Efficiency y EltaMD (sin descontinuados).
-- precio_costo = precio médico / PVL con IVA (BioElite no grava IVA). Productos nuevos: precio_venta = 0, stock 0,
-- stock_minimo 0 (catálogo, no alertar). Gioval pone el precio en Farmacia → Inventario.
-- Productos que ya estaban (pedido OmicronLab): NO se toca stock ni costo; solo precio_venta = máximo sugerido si estaba en 0.
BEGIN;

SELECT v.n, 'Farmacia' FROM (VALUES ('HD Cosmetic Efficiency'), ('EltaMD')) AS v(n)
WHERE NOT EXISTS (SELECT 1 FROM farmacia_proveedores p WHERE p.nombre = v.n);

CREATE TEMP TABLE _cat (codigo TEXT, nombre TEXT, costo NUMERIC(10,2), venta_max NUMERIC(10,2), proveedor TEXT, categoria TEXT, ean TEXT) ON COMMIT DROP;

UPDATE farmacia_productos fp SET precio_venta = c.venta_max, actualizado_en = NOW()
FROM _cat c
WHERE fp.codigo_proveedor = c.codigo AND fp.activo AND fp.precio_venta = 0 AND c.venta_max IS NOT NULL;

SELECT c.nombre, c.codigo, c.categoria, c.costo, 0, 0, 0, (SELECT id FROM farmacia_proveedores WHERE nombre = c.proveedor ORDER BY id LIMIT 1), c.ean
FROM _cat c
WHERE NOT EXISTS (SELECT 1 FROM farmacia_productos fp WHERE fp.codigo_proveedor = c.codigo);

COMMIT;
